// Absender, Betreff und Text aus der Mail holen.
// Die IMAP-Node liefert "from" als Objekt: { value: [{address, name}], text, html }.
// Aeltere Formate liefern einen reinen String - beides wird unterstuetzt.
function absenderAus(feld) {
  if (!feld) return { mail: '', name: '' };
  if (typeof feld === 'string') {
    const treffer = feld.match(/<([^>]+)>/);
    return {
      mail: (treffer ? treffer[1] : feld).trim().toLowerCase(),
      name: feld.replace(/<[^>]*>/, '').replace(/"/g, '').trim()
    };
  }
  const erster = Array.isArray(feld.value) && feld.value[0] ? feld.value[0] : {};
  return {
    mail: String(erster.address || '').trim().toLowerCase(),
    name: String(erster.name || '').trim()
  };
}

const mail = $json;
const absender = absenderAus(mail.from);
const betreff = String(mail.subject || '').trim();
const text = String(mail.text || mail.textAsHtml || '').trim().slice(0, 6000);

return {
  json: {
    absenderMail: absender.mail,
    absenderName: absender.name,
    betreff,
    mailText: `Von: ${absender.mail}\nBetreff: ${betreff}\n\n${text}`
  }
};

