parameters.jsCode:
// Ergebnis des Information Extractors auswerten und ein Join-Ticket bauen.
// Gibt bewusst NICHTS zurueck, wenn die Mail keine echte Anfrage war -
// dann entsteht kein Ticket und das Tageskontingent bleibt unberuehrt.

// Der Extractor liefert das Ergebnis je nach Version unter "output" oder direkt.
const analyse = $json.output ?? $json;
const quelle = $('Mail aufbereiten').item.json;

if (analyse.istEchteAnfrage !== true) {
  return null;
}

// Das Modell liefert ISO (JJJJ-MM-TT); Join erwartet TT/MM/JJJJ.
// Umwandlung im Code statt im Prompt, weil das Format sonst schwankt.
function alsJoinDatum(iso) {
  if (!iso) return '';
  const teile = String(iso).trim().split('-');
  if (teile.length !== 3) return '';
  const [jahr, monat, tag] = teile;
  return `${tag}/${monat}/${jahr}`;
}

const ticket = {
  id: Date.now(),
  title: String(analyse.title || quelle.betreff || 'Anfrage ohne Titel').slice(0, 120),
  description: `${String(analyse.description || '').trim()} Dieses Ticket wurde KI-generiert.`,
  date: alsJoinDatum(analyse.deadline),
  priority: analyse.priority || 'medium',
  category: analyse.category || 'user-story',
  status: 'triage',
  assigned: [],
  subtasks: [],
  creator: {
    email: quelle.absenderMail,
    name: quelle.absenderName || quelle.absenderMail,
    type: 'extern'
  }
};

return { json: { ticket, absenderMail: quelle.absenderMail, betreff: quelle.betreff } };
